use super::*;use super::super::trail::{self,raw_set};
fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
struct W{scenario:usize,u:[u8;192],b:[u8;88],w:[u8;44],group:[u8;100],fragments:Vec<[u8;18]>,jobs:trail::State,frames:Vec<Vec<[i16;4]>>,queue:Vec<u8>,calls:Vec<u32>,crt:usize,busy:u8,fail:bool,start:bool}
fn word(b:&mut[u8],at:usize,n:i16){b[at..at+2].copy_from_slice(&n.to_le_bytes());}
fn get(b:&[u8],at:usize)->i16{i16::from_le_bytes(b[at..at+2].try_into().unwrap())}
